package co.com.nequi.ticketing.model.shared;

import java.util.Objects;
import java.util.UUID;

/**
 * Unique identifier of an event, generated by the server when the event is created.
 *
 * @param value the UUID that identifies the event
 */
public record EventId(UUID value) {

    public EventId {
        Objects.requireNonNull(value, "Event id value must not be null");
    }

    /**
     * Generates a new random event identifier.
     *
     * @return a new event identifier
     */
    public static EventId newId() {
        return new EventId(UUID.randomUUID());
    }
}
